    osSemaphoreNew(1, 0, NULL); /* Ereignis, anfangs leer */
if (sem == NULL) { Error_Handler(); }

osStatus_t st = osSemaphoreAcquire(sem, 10);
if (st != osOK) {
    /* Timeout oder Parameter: Ressource nicht anfassen */
